'use client';

import React, { useEffect, useId, useRef, useState } from 'react';
import { ArrowRight, ChevronLeft, ChevronRight, Globe, MapPin } from 'lucide-react';

export interface CompetitionItem {
  id: string;
  title: string;
  organization: string;
  location: string;
  isOnline: boolean;
  registeredCount?: string;
  logo: React.ReactNode;
}

// The supplied screenshot is embedded once as a sprite. The SVG viewBox
// displays only each logo, so no extra public assets or image domains are needed.
const REFERENCE_IMAGE = 'data:image/png;base64,';

function ReferenceLogo({ viewBox }: { viewBox: string }) {
  return (
    <svg viewBox={viewBox} className="h-full w-full" aria-hidden="true" overflow="hidden">
      <image href={REFERENCE_IMAGE} width="1545" height="365" />
    </svg>
  );
}

const COMPETITIONS_DATA: CompetitionItem[] = [
  {
    id: 'strathack',
    title: 'StratHack',
    organization: 'Loyola College (LC), Chennai',
    location: 'Loyola College, Chennai, Tamil Nadu',
    isOnline: false,
    logo: <ReferenceLogo viewBox="454 141 70 69" />,
  },
  {
    id: 'financial-efficiency',
    title: 'The Financial Efficiency Case Challenge',
    organization: 'Cephas Consultancy Services Private Limited',
    location: 'Online',
    isOnline: true,
    logo: <ReferenceLogo viewBox="857 141 68 69" />,
  },
  {
    id: 'technology-solutions',
    title: 'Technology Solutions Challenge',
    organization: 'Panimalar Engineering College (PEC), Chennai',
    location: 'Online',
    isOnline: true,
    logo: <ReferenceLogo viewBox="1259 141 68 69" />,
  },
  // Extra supplied cards remain available using the carousel arrows.
  {
    id: 'comp-4',
    title: "L'Oréal Brandstorm 2026 - Innovation Challenge",
    organization: "L'Oréal",
    location: 'Online',
    isOnline: true,
    logo: <span className="font-serif text-[12px] font-bold tracking-wide">L&apos;ORÉAL</span>,
  },
  {
    id: 'comp-5',
    title: 'Tata Imagination Challenge 2026',
    organization: 'Tata Sons',
    location: 'Online',
    isOnline: true,
    logo: <span className="text-lg font-black text-[#00539f]">TATA</span>,
  },
];

interface CompetitionsSectionProps {
  items?: CompetitionItem[];
  onSelect?: (item: CompetitionItem) => void;
  onViewAll?: () => void;
  viewAllHref?: string;
}

export const CompetitionsSection: React.FC<CompetitionsSectionProps> = ({
  items = COMPETITIONS_DATA,
  onSelect,
  onViewAll,
  viewAllHref = '/competitions',
}) => {
  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const headingId = useId();
  const carouselId = useId();
  const [canGoBack, setCanGoBack] = useState(false);
  const [canGoForward, setCanGoForward] = useState(false);

  useEffect(() => {
    const container = scrollContainerRef.current;
    if (!container) return;
    const update = () => {
      setCanGoBack(container.scrollLeft > 2);
      setCanGoForward(container.scrollLeft + container.clientWidth < container.scrollWidth - 2);
    };
    update();
    container.addEventListener('scroll', update, { passive: true });
    const observer = new ResizeObserver(update);
    observer.observe(container);
    Array.from(container.children).forEach((child) => observer.observe(child));
    return () => {
      container.removeEventListener('scroll', update);
      observer.disconnect();
    };
  }, [items]);

  const handleScroll = (direction: 'left' | 'right') => {
    const container = scrollContainerRef.current;
    const card = container?.firstElementChild as HTMLElement | null;
    if (!container || !card) return;
    const gap = parseFloat(getComputedStyle(container).columnGap) || 0;
    container.scrollBy({
      left: (card.getBoundingClientRect().width + gap) * (direction === 'right' ? 1 : -1),
      behavior: window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth',
    });
  };

  const viewAllClass = 'inline-flex h-[38px] shrink-0 items-center justify-center gap-2 rounded-full border border-[#b8d8ff] bg-[#f3f8ff] px-4 text-[14px] font-medium text-[#0073e6] transition-colors hover:bg-[#e6f1ff] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#0073e6] sm:text-[15px]';
  const viewAllContent = <><span>View All</span><span className="flex h-[16px] w-[16px] items-center justify-center rounded-full bg-[#0073e6] text-white"><ArrowRight size={11} strokeWidth={2.5} aria-hidden="true" /></span></>;
  const arrowClass = 'absolute top-1/2 z-10 flex h-[38px] w-[38px] -translate-y-1/2 items-center justify-center rounded-full border border-[#d0d0d0] bg-white text-[#444] shadow-[0_2px_8px_rgba(0,0,0,0.06)] transition-all hover:border-[#0073e6] hover:text-[#0073e6] hover:shadow-md outline-none focus:outline-none focus:ring-0 focus-visible:outline-none focus-visible:ring-0 [-webkit-tap-highlight-color:transparent]';

  return (
    <section aria-labelledby={headingId} className="mx-auto w-full min-w-0 max-w-[980px] bg-white -mt-3 sm:-mt-4 pt-0 pb-3 px-2 sm:px-4 font-[Arial,Helvetica,sans-serif]">
      <div className="mb-3 flex items-center justify-between gap-4">
        <div className="relative min-w-0 pl-3.5 before:absolute before:inset-y-0 before:left-0 before:w-[4px] before:rounded-r-full before:bg-[#0073e6]">
          <h2 id={headingId} className="text-[21px] font-semibold leading-[1.2] text-[#383838] sm:text-[26px]">Competitions</h2>
          <p className="mt-0.5 text-[13px] font-normal leading-[20px] text-[#777] sm:text-[15px]">Uncover the most talked-about competitions today.</p>
        </div>
        {onViewAll ? <button type="button" onClick={onViewAll} className={viewAllClass}>{viewAllContent}</button> : <a href={viewAllHref} className={viewAllClass}>{viewAllContent}</a>}
      </div>

      <div className="relative">
        <div
          id={carouselId}
          ref={scrollContainerRef}
          role="region"
          aria-label="Competition cards"
          className="grid min-w-0 snap-x snap-mandatory auto-cols-[250px] grid-flow-col gap-4 overflow-x-auto overscroll-x-contain rounded-[16px] [scrollbar-width:none] [&::-webkit-scrollbar]:hidden outline-none focus:outline-none focus:ring-0 focus-visible:outline-none focus-visible:ring-0 [-webkit-tap-highlight-color:transparent] sm:auto-cols-[calc((100%_-_16px)/2)] md:auto-cols-[calc((100%_-_32px)/3)] lg:auto-cols-[calc((100%_-_32px)/3)]"
        >
          {items.map((item) => {
            const content = <>
              <div className="flex h-[86px] items-center justify-between gap-2.5 rounded-[13px] bg-gradient-to-b from-[#f8f4ff] to-[#f1f8fe] px-3">
                <div className="flex min-w-0 items-center gap-1.5 text-[13px] font-normal text-[#383838]">
                  {item.isOnline ? <Globe size={15} strokeWidth={2.3} className="shrink-0 text-[#7b7b7b]" aria-hidden="true" /> : <MapPin size={15} strokeWidth={2.3} className="shrink-0 text-[#7b7b7b]" aria-hidden="true" />}
                  <span className="truncate" title={item.location}>{item.location}</span>
                </div>
                <div className="flex h-[58px] w-[58px] shrink-0 items-center justify-center overflow-hidden rounded-[11px] border border-[#b4b4b4] bg-white p-1">{item.logo}</div>
              </div>
              <div className="min-w-0 px-3 pb-2.5 pt-2">
                <h3 className="truncate text-[15px] font-semibold leading-[21px] text-[#383838] transition-colors group-hover:text-[#0073e6] group-active:text-[#0073e6] sm:text-[16px]" title={item.title}>{item.title}</h3>
                <p className="mt-0.5 truncate text-[12.5px] font-normal leading-[17px] text-[#666] sm:text-[13px]" title={item.organization}>{item.organization}</p>
              </div>
            </>;
            const cardClass = 'group block h-[168px] min-w-0 snap-start overflow-hidden rounded-[16px] border border-[#dedede] bg-white p-1 text-left cursor-pointer transition-shadow hover:shadow-[0_4px_14px_rgba(0,0,0,0.06)] outline-none focus:outline-none focus:ring-0 focus-visible:outline-none focus-visible:ring-0 [-webkit-tap-highlight-color:transparent] select-none';
            return onSelect ? <button key={item.id} type="button" onClick={() => onSelect(item)} className={cardClass}>{content}</button> : <article key={item.id} className={cardClass}>{content}</article>;
          })}
        </div>

        {canGoBack && <button type="button" onClick={() => handleScroll('left')} aria-label="Previous competitions" aria-controls={carouselId} className={`${arrowClass} -left-2.5 sm:-left-3 xl:-left-[44px]`}><ChevronLeft size={17} strokeWidth={2.2} aria-hidden="true" /></button>}
        {canGoForward && <button type="button" onClick={() => handleScroll('right')} aria-label="Next competitions" aria-controls={carouselId} className={`${arrowClass} -right-2.5 sm:-right-3 xl:-right-[44px]`}><ChevronRight size={17} strokeWidth={2.2} aria-hidden="true" /></button>}
      </div>
    </section>
  );
};

export default CompetitionsSection;
